(function(){if(!location.pathname.includes('/tools/events/register_cdo/code/'))return;function start(){var page=document.querySelector('#RegisterSinglePage.view_receipt'),body=document.getElementById('RegisterBody');if(!page||!body||!page.querySelector('a[href*="eventid=23993"]'))return;document.body.classList.add('tc-ente-receipt');var hero=document.createElement('div');hero.innerHTML="<section id=\"tcEntebbeConfirmed\"><div class=\"tc-receipt-kicker\">Reservation received</div><h1>You’re on the guest list.</h1><p>Thank you for joining us for The Raid on Entebbe, firsthand.</p><div class=\"tc-receipt-details\"><div><span>When</span><strong>Tuesday, October 20, 2026<br>7:00 PM</strong></div><div><span>Where</span><strong>Coquitlam<br>Address provided before the event</strong></div></div><p class=\"tc-receipt-note\">Light refreshments will be served. We look forward to seeing you.</p></section>";page.insertBefore(hero.firstElementChild,body);var thanks=body.querySelector('.thank_you');if(thanks)thanks.parentElement.classList.add('tc-receipt-old-intro');var summary=document.getElementById('ReservationSummary');if(summary){summary.firstElementChild.textContent='Your reserved seats';summary.querySelectorAll('.item-table tr.item').forEach(function(row){var cell=row.children[3];if(cell&&cell.querySelector('span'))cell.querySelector('span').textContent='Event attendee';});}Array.from(body.children).forEach(function(el){if(el.textContent.trim()==='Reservation Receipt')el.classList.add('tc-receipt-duplicate-title');if(el.querySelector('.total_text'))el.classList.add('tc-receipt-details-section');});var total=body.querySelector('.total_text .label');if(total)total.textContent='Total contribution';var donation=body.querySelector('.donation_text .label');if(donation)donation.textContent='Contribution';var additional=body.querySelector('.tc-receipt-details-section > .uppercase');if(additional)additional.textContent='Reservation details';var button=document.getElementById('AnotherReservationButton');if(button){button.textContent='Reserve additional seats';}var help=document.createElement('p');help.className='tc-receipt-contact';help.innerHTML='Questions? <a href="mailto:info@jewishtricities.com">info@jewishtricities.com</a>';body.appendChild(help);}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();})();